-- Упражнения книги 19, глава 10 (Администрирование Linux). Файл строит автор-скрипт (не в репозитории); после правок можно редактировать и вручную.

INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-stp-states', 0, 'func', 'Мост и состояния портов STP', 'Смоделируйте мост без VLAN. ports - словарь {порт: состояние}, состояние одно из disabled, blocking, listening, learning, forwarding. frames - список [порт_входа, mac_отправителя, mac_получателя]. Напишите функцию bridge_run(ports, frames): верните кортеж (outs, fdb), где outs - список по кадрам: отсортированный список портов, в которые мост отправил кадр (пустой список, если кадр отброшен или не отправлен), а fdb - итоговый словарь {mac: порт}. Правила по порядку. Кадр с недопустимым отправителем (младший бит первого байта равен 1, то есть групповой адрес, или 00:00:00:00:00:00) отбрасывается без изучения. Кадр на порту disabled, blocking или listening отбрасывается без изучения. Иначе отправитель изучается: fdb[отправитель] = порт входа (запись перезаписывается). Кадр на порту learning после изучения отбрасывается. Кадр на порту forwarding пересылается: если получатель групповой (младший бит первого байта 1, включая ff:ff:ff:ff:ff:ff) или его нет в fdb, кадр рассылается во все порты forwarding, кроме порта входа; если получатель в fdb, кадр уходит только на его порт, при условии что это не порт входа и он в состоянии forwarding, иначе не отправляется никуда.', 'def bridge_run(ports, frames):
    pass
', 'Первый байт: int(mac.split('':'')[0], 16) & 1. Порядок важен: сначала отбраковка, потом изучение, потом решение по получателю.', '{"func": "bridge_run", "tests": [{"args": [{"p1": "forwarding", "p2": "forwarding", "p3": "forwarding", "p4": "forwarding"}, [["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"]]], "expected": {"__tuple__": [[["p2", "p3", "p4"], ["p1"], ["p2"]], {"52:54:00:00:00:0a": "p1", "52:54:00:00:00:0b": "p2"}]}}, {"args": [{"p1": "forwarding", "p2": "forwarding", "p3": "forwarding", "p4": "forwarding"}, [["p1", "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["p3", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["p3", "52:54:00:00:00:0c", "52:54:00:00:00:0b"], ["p4", "52:54:00:00:00:0d", "01:00:5e:00:00:01"]]], "expected": {"__tuple__": [[["p2", "p3", "p4"], ["p1"], [], ["p1", "p2", "p3"]], {"52:54:00:00:00:0a": "p1", "52:54:00:00:00:0b": "p3", "52:54:00:00:00:0c": "p3", "52:54:00:00:00:0d": "p4"}]}}, {"args": [{"p1": "forwarding", "p2": "blocking", "p3": "learning", "p4": "forwarding", "p5": "listening", "p6": "disabled"}, [["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["p3", "52:54:00:00:00:0c", "52:54:00:00:00:0a"], ["p4", "52:54:00:00:00:0d", "52:54:00:00:00:0c"], ["p5", "52:54:00:00:00:0e", "52:54:00:00:00:0a"], ["p6", "52:54:00:00:00:0e", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[["p4"], [], [], [], [], []], {"52:54:00:00:00:0a": "p1", "52:54:00:00:00:0c": "p3", "52:54:00:00:00:0d": "p4"}]}}, {"args": [{"p1": "forwarding", "p2": "blocking", "p3": "learning", "p4": "forwarding", "p5": "listening", "p6": "disabled"}, [["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p4", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["p3", "52:54:00:00:00:0c", "52:54:00:00:00:0a"], ["p4", "52:54:00:00:00:0a", "52:54:00:00:00:0c"], ["p1", "52:54:00:00:00:0d", "52:54:00:00:00:0c"]]], "expected": {"__tuple__": [[["p4"], ["p1"], [], [], []], {"52:54:00:00:00:0a": "p4", "52:54:00:00:00:0b": "p4", "52:54:00:00:00:0c": "p3", "52:54:00:00:00:0d": "p1"}]}}, {"args": [{"p1": "forwarding", "p2": "forwarding", "p3": "forwarding", "p4": "forwarding"}, [["p1", "01:00:5e:00:00:01", "52:54:00:00:00:0a"], ["p2", "00:00:00:00:00:00", "52:54:00:00:00:0a"], ["p2", "52:54:00:00:00:0a", "00:00:00:00:00:00"]]], "expected": {"__tuple__": [[[], [], ["p1", "p3", "p4"]], {"52:54:00:00:00:0a": "p2"}]}}, {"args": [{"p1": "forwarding", "p2": "forwarding", "p3": "forwarding", "p4": "forwarding"}, [["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p2", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p3", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["p2", "52:54:00:00:00:0c", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[["p2", "p3", "p4"], ["p1", "p3", "p4"], ["p2"], []], {"52:54:00:00:00:0a": "p2", "52:54:00:00:00:0b": "p3", "52:54:00:00:00:0c": "p2"}]}}, {"args": [{"p1": "forwarding"}, [["p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["p1", "52:54:00:00:00:0b", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[[], []], {"52:54:00:00:00:0a": "p1", "52:54:00:00:00:0b": "p1"}]}}, {"args": [{"p1": "forwarding", "p2": "forwarding", "p3": "forwarding", "p4": "forwarding"}, []], "expected": {"__tuple__": [[], {}]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-fdb-ageing', 1, 'func', 'Старение записей FDB', 'Смоделируйте обучение моста во времени. Все порты в состоянии forwarding, VLAN нет. frames - список [t, порт_входа, mac_отправителя, mac_получателя], t - секунды, значения не убывают. Напишите функцию fdb_decisions(ageing, frames): для каждого кадра верните строку: ''flood'' (кадр разослан во все остальные порты), ''port:<имя>'' (кадр ушёл в один порт) или ''filter'' (получатель найден за портом входа, кадр не пересылается). Порядок действий для кадра в момент t: 1) если ageing > 0, отправитель изучается как запись (порт входа, время t), уже существующая запись перезаписывается и её время обновляется; при ageing = 0 ничего не изучается (мост всегда рассылает); 2) ищется запись получателя; запись устарела, если t - время_записи >= ageing, устаревшая запись удаляется и считается отсутствующей; 3) если получатель групповой (младший бит первого байта равен 1) или записи нет - ''flood''; если порт записи равен порту входа - ''filter''; иначе ''port:<порт записи>''. Пересылка кадров получателю время его записи не обновляет.', 'def fdb_decisions(ageing, frames):
    pass
', 'Храните table[mac] = (порт, время). Сначала запись отправителя, потом проверка возраста записи получателя.', '{"func": "fdb_decisions", "tests": [{"args": [300, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [1, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [2, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"]]], "expected": ["flood", "port:p1", "port:p2"]}, {"args": [30, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [10, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [29, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [31, "p2", "52:54:00:00:00:0c", "52:54:00:00:00:0a"], [40, "p2", "52:54:00:00:00:0c", "52:54:00:00:00:0b"]]], "expected": ["flood", "port:p1", "port:p2", "port:p1", "flood"]}, {"args": [30, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [20, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [29, "p1", "52:54:00:00:00:0c", "52:54:00:00:00:0a"], [30, "p2", "52:54:00:00:00:0d", "52:54:00:00:00:0a"], [59, "p3", "52:54:00:00:00:0e", "52:54:00:00:00:0b"], [60, "p3", "52:54:00:00:00:0e", "52:54:00:00:00:0b"]]], "expected": ["flood", "port:p1", "filter", "flood", "flood", "flood"]}, {"args": [0, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [0, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [1, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"]]], "expected": ["flood", "flood", "flood"]}, {"args": [10, [[0, "p1", "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], [0, "p1", "52:54:00:00:00:0b", "01:00:5e:00:00:01"], [5, "p2", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [5, "p3", "52:54:00:00:00:0c", "52:54:00:00:00:0a"]]], "expected": ["flood", "flood", "port:p1", "port:p2"]}, {"args": [100, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0b"], [50, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0c"], [60, "p3", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [90, "p1", "52:54:00:00:00:0c", "52:54:00:00:00:0b"], [149, "p2", "52:54:00:00:00:0d", "52:54:00:00:00:0a"], [150, "p2", "52:54:00:00:00:0d", "52:54:00:00:00:0a"]]], "expected": ["flood", "flood", "port:p1", "port:p3", "flood", "flood"]}, {"args": [5, [[0, "p1", "52:54:00:00:00:0a", "52:54:00:00:00:0a"], [4, "p1", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [5, "p2", "52:54:00:00:00:0b", "52:54:00:00:00:0a"], [10, "p2", "52:54:00:00:00:0a", "52:54:00:00:00:0b"]]], "expected": ["filter", "filter", "flood", "flood"]}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-vlan-forward', 2, 'func', 'Мост с VLAN-фильтрацией: решение о пересылке', 'Смоделируйте мост с vlan_filtering 1. ports - словарь {порт: {"pvid": число или None, "vlans": {"<vid>": "untagged" или "tagged"}}} (ключи vlans - строки с номером VLAN; значение untagged означает, что на выходе тег снимается). frames - список [порт_входа, тег, mac_отправителя, mac_получателя], тег - число или None (None и 0 означают кадр без тега). Напишите функцию vlan_forward(ports, frames): верните (outs, fdb). Для каждого кадра: отправитель с младшим битом первого байта 1 или 00:00:00:00:00:00 - кадр отбрасывается (пустой список). Кадр без тега относится к pvid порта, при pvid None он отбрасывается; кадр с тегом принимается, только если номер есть в vlans порта, иначе отбрасывается. Номер VLAN кадра назовём vid. Отправитель изучается: ключ (vid, mac) -> порт входа. Получатель: если он групповой (младший бит первого байта 1) или (vid, mac) нет в таблице - рассылка на все порты, кроме порта входа; иначе единственный порт записи, если это не порт входа. На любой порт кадр попадает, только если vid есть в его vlans; элемент результата - пара (порт, тег): тег равен vid, если VLAN на этом порту tagged, и None, если untagged. Список outs для кадра отсортирован по имени порта. fdb - итоговый отсортированный список кортежей (vid, mac, порт).', 'def vlan_forward(ports, frames):
    pass
', 'Таблица ключуется парой (vid, mac). Членство VLAN проверяется отдельно для порта входа и для каждого порта выхода.', '{"func": "vlan_forward", "tests": [{"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, [["vnet0", null, "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["vnet1", null, "52:54:00:00:00:0b", "ff:ff:ff:ff:ff:ff"], ["eth0", 10, "52:54:00:00:00:0c", "52:54:00:00:00:0a"], ["vnet0", null, "52:54:00:00:00:0a", "52:54:00:00:00:0c"]]], "expected": {"__tuple__": [[[{"__tuple__": ["eth0", 10]}, {"__tuple__": ["vnet2", null]}], [{"__tuple__": ["eth0", 20]}, {"__tuple__": ["vnet2", 20]}], [{"__tuple__": ["vnet0", null]}], [{"__tuple__": ["eth0", 10]}]], [{"__tuple__": [10, "52:54:00:00:00:0a", "vnet0"]}, {"__tuple__": [10, "52:54:00:00:00:0c", "eth0"]}, {"__tuple__": [20, "52:54:00:00:00:0b", "vnet1"]}]]}}, {"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, [["eth0", 20, "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["vnet1", null, "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["eth0", 20, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["vnet2", 20, "52:54:00:00:00:0d", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[[{"__tuple__": ["vnet1", null]}, {"__tuple__": ["vnet2", 20]}], [{"__tuple__": ["eth0", 20]}], [{"__tuple__": ["vnet1", null]}], [{"__tuple__": ["eth0", 20]}]], [{"__tuple__": [20, "52:54:00:00:00:0a", "eth0"]}, {"__tuple__": [20, "52:54:00:00:00:0b", "vnet1"]}, {"__tuple__": [20, "52:54:00:00:00:0d", "vnet2"]}]]}}, {"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, [["eth0", null, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["eth0", 30, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["eth0", 0, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["vnet0", 20, "52:54:00:00:00:0a", "52:54:00:00:00:0b"]]], "expected": {"__tuple__": [[[], [], [], []], []]}}, {"args": [{"t1": {"pvid": 1, "vlans": {"1": "untagged", "30": "tagged"}}, "t2": {"pvid": 1, "vlans": {"1": "untagged", "30": "tagged"}}, "a1": {"pvid": 30, "vlans": {"30": "untagged"}}, "a2": {"pvid": null, "vlans": {"1": "untagged"}}}, [["a1", null, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["t1", 30, "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["a1", null, "52:54:00:00:00:0a", "52:54:00:00:00:0b"], ["a2", null, "52:54:00:00:00:0c", "52:54:00:00:00:0a"], ["t2", null, "52:54:00:00:00:0d", "52:54:00:00:00:0c"]]], "expected": {"__tuple__": [[[{"__tuple__": ["t1", 30]}, {"__tuple__": ["t2", 30]}], [{"__tuple__": ["a1", null]}], [{"__tuple__": ["t1", 30]}], [], [{"__tuple__": ["a2", null]}, {"__tuple__": ["t1", null]}]], [{"__tuple__": [1, "52:54:00:00:00:0d", "t2"]}, {"__tuple__": [30, "52:54:00:00:00:0a", "a1"]}, {"__tuple__": [30, "52:54:00:00:00:0b", "t1"]}]]}}, {"args": [{"t1": {"pvid": 1, "vlans": {"1": "untagged", "30": "tagged"}}, "t2": {"pvid": 1, "vlans": {"1": "untagged", "30": "tagged"}}, "a1": {"pvid": 30, "vlans": {"30": "untagged"}}, "a2": {"pvid": null, "vlans": {"1": "untagged"}}}, [["a2", 0, "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["t1", null, "52:54:00:00:00:0b", "01:00:5e:00:00:01"], ["t2", 1, "52:54:00:00:00:0c", "52:54:00:00:00:0a"], ["t2", 30, "52:54:00:00:00:0c", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[[], [{"__tuple__": ["a2", null]}, {"__tuple__": ["t2", null]}], [{"__tuple__": ["a2", null]}, {"__tuple__": ["t1", null]}], [{"__tuple__": ["a1", null]}, {"__tuple__": ["t1", 30]}]], [{"__tuple__": [1, "52:54:00:00:00:0b", "t1"]}, {"__tuple__": [1, "52:54:00:00:00:0c", "t2"]}, {"__tuple__": [30, "52:54:00:00:00:0c", "t2"]}]]}}, {"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, [["vnet2", null, "01:00:5e:00:00:01", "52:54:00:00:00:0a"], ["vnet2", null, "00:00:00:00:00:00", "52:54:00:00:00:0a"], ["vnet2", null, "52:54:00:00:00:0a", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[[], [], []], [{"__tuple__": [10, "52:54:00:00:00:0a", "vnet2"]}]]}}, {"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, []], "expected": {"__tuple__": [[], []]}}, {"args": [{"eth0": {"pvid": null, "vlans": {"10": "tagged", "20": "tagged"}}, "vnet0": {"pvid": 10, "vlans": {"10": "untagged"}}, "vnet1": {"pvid": 20, "vlans": {"20": "untagged"}}, "vnet2": {"pvid": 10, "vlans": {"10": "untagged", "20": "tagged"}}}, [["vnet2", 10, "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["vnet2", 20, "52:54:00:00:00:0a", "ff:ff:ff:ff:ff:ff"], ["eth0", 10, "52:54:00:00:00:0b", "52:54:00:00:00:0a"], ["eth0", 20, "52:54:00:00:00:0b", "52:54:00:00:00:0a"]]], "expected": {"__tuple__": [[[{"__tuple__": ["eth0", 10]}, {"__tuple__": ["vnet0", null]}], [{"__tuple__": ["eth0", 20]}, {"__tuple__": ["vnet1", null]}], [{"__tuple__": ["vnet2", null]}], [{"__tuple__": ["vnet2", 20]}]], [{"__tuple__": [10, "52:54:00:00:00:0a", "vnet2"]}, {"__tuple__": [10, "52:54:00:00:00:0b", "eth0"]}, {"__tuple__": [20, "52:54:00:00:00:0a", "vnet2"]}, {"__tuple__": [20, "52:54:00:00:00:0b", "eth0"]}]]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-vlan-show-parse', 3, 'func', 'Разбор bridge vlan show', 'Напишите функцию parse_vlan_show(text): text - вывод команды bridge vlan show. Первая строка - заголовок ''port vlan-id'' (его пропустите, пустые строки тоже). Строка, начинающаяся с непробела, открывает новый порт: первое слово - имя порта, дальше VLAN-запись; строка, начинающаяся с пробела, - ещё одна запись того же порта. Запись - это номер VLAN или диапазон вида 10-12 (оба конца включительно), за которым могут идти флаги PVID и Egress Untagged (два слова). Верните словарь {порт: {"pvid": номер VLAN с флагом PVID или None, "untagged": отсортированный список VLAN с флагом Egress Untagged, "vlans": отсортированный список всех VLAN порта}}. Диапазоны разворачиваются в отдельные номера; если у диапазона есть PVID, pvid - его первый номер. Порт без записей в выводе не появляется.', 'def parse_vlan_show(text):
    pass
', 'Строка с отступом принадлежит последнему порту. ''Untagged'' in words хватает для флага Egress Untagged.', '{"func": "parse_vlan_show", "tests": [{"args": ["port              vlan-id\neth1              1 PVID Egress Untagged\n                  2\n                  3\nbr0               1 PVID Egress Untagged\nveth1             1 Egress Untagged\n                  2\nveth2             1 Egress Untagged\n                  2 PVID Egress Untagged\nveth3             1 Egress Untagged\n                  3 PVID Egress Untagged\n"], "expected": {"eth1": {"pvid": 1, "untagged": [1], "vlans": [1, 2, 3]}, "br0": {"pvid": 1, "untagged": [1], "vlans": [1]}, "veth1": {"pvid": null, "untagged": [1], "vlans": [1, 2]}, "veth2": {"pvid": 2, "untagged": [1, 2], "vlans": [1, 2]}, "veth3": {"pvid": 3, "untagged": [1, 3], "vlans": [1, 3]}}}, {"args": ["port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n"], "expected": {"eth0": {"pvid": null, "untagged": [1], "vlans": [1, 10, 20]}, "vnet0": {"pvid": 20, "untagged": [20], "vlans": [20]}, "vnet1": {"pvid": 10, "untagged": [10], "vlans": [10, 20]}, "br0": {"pvid": 1, "untagged": [1], "vlans": [1]}}}, {"args": ["port              vlan-id\neno1              10-12\n                  100 PVID Egress Untagged\nvnet7             1 PVID Egress Untagged\n"], "expected": {"eno1": {"pvid": 100, "untagged": [100], "vlans": [10, 11, 12, 100]}, "vnet7": {"pvid": 1, "untagged": [1], "vlans": [1]}}}, {"args": ["port              vlan-id\nvnet3             5\n"], "expected": {"vnet3": {"pvid": null, "untagged": [], "vlans": [5]}}}, {"args": ["port              vlan-id\nbond0             1 Egress Untagged\n                  50\n                  60\nvnet0             50 PVID Egress Untagged\nvnet1             60\n"], "expected": {"bond0": {"pvid": null, "untagged": [1], "vlans": [1, 50, 60]}, "vnet0": {"pvid": 50, "untagged": [50], "vlans": [50]}, "vnet1": {"pvid": null, "untagged": [], "vlans": [60]}}}, {"args": [""], "expected": {}}, {"args": ["port              vlan-id\n"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-fdb-learned', 4, 'func', 'Изученные адреса из bridge fdb show', 'Напишите функцию learned_macs(text, bridge): text - вывод bridge fdb show, строки вида ''<mac> dev <порт> [vlan N] [флаги] [master <мост>] [состояние]''. Динамическая запись моста bridge - это строка, у которой последние два слова ''master <bridge>'' (после имени моста нет слова состояния permanent, static или stale) и среди слов нет extern_learn (такие записи изучены не самим мостом и не стареют). Строки без ''master'' (например ''self permanent''), записи других мостов и записи с состоянием в конце пропускайте. Верните словарь {порт: отсортированный список кортежей (mac, vlan)}, vlan равен 0, если слова vlan в строке нет; mac приведите к нижнему регистру. Порты без динамических записей в словарь не попадают.', 'def learned_macs(text, bridge):
    pass
', 'line.split() и проверка w[-2:] == [''master'', bridge]; номер VLAN - слово после ''vlan''.', '{"func": "learned_macs", "tests": [{"args": ["33:33:00:00:00:01 dev eth0 self permanent\n01:00:5e:00:00:01 dev eth0 self permanent\n52:54:00:aa:bb:01 dev eth0 master br0 permanent\nfe:54:00:11:22:33 dev vnet0 master br0 permanent\n52:54:00:11:22:33 dev vnet0 master br0\n52:54:00:44:55:66 dev vnet1 master br0\nfe:54:00:44:55:66 dev vnet1 master br0 permanent\n3c:fd:fe:00:11:22 dev eth0 master br0\n", "br0"], "expected": {"vnet0": [{"__tuple__": ["52:54:00:11:22:33", 0]}], "vnet1": [{"__tuple__": ["52:54:00:44:55:66", 0]}], "eth0": [{"__tuple__": ["3c:fd:fe:00:11:22", 0]}]}}, {"args": ["fe:54:00:11:22:33 dev vnet0 vlan 1 master br0 permanent\nfe:54:00:11:22:33 dev vnet0 master br0 permanent\n52:54:00:11:22:33 dev vnet0 vlan 20 master br0\n52:54:00:44:55:66 dev vnet1 vlan 10 master br0\n52:54:00:44:55:77 dev vnet1 vlan 20 master br0\na0:36:9f:00:00:01 dev eth0 vlan 20 master br0 stale\na0:36:9f:00:00:02 dev eth0 vlan 10 master br0\na0:36:9f:00:00:03 dev eth0 vlan 10 extern_learn master br0\n52:54:00:00:00:99 dev vnet9 vlan 30 master br1\n52:54:00:aa:bb:01 dev br0 vlan 1 master br0 permanent\n", "br0"], "expected": {"vnet0": [{"__tuple__": ["52:54:00:11:22:33", 20]}], "vnet1": [{"__tuple__": ["52:54:00:44:55:66", 10]}, {"__tuple__": ["52:54:00:44:55:77", 20]}], "eth0": [{"__tuple__": ["a0:36:9f:00:00:02", 10]}]}}, {"args": ["fe:54:00:11:22:33 dev vnet0 vlan 1 master br0 permanent\nfe:54:00:11:22:33 dev vnet0 master br0 permanent\n52:54:00:11:22:33 dev vnet0 vlan 20 master br0\n52:54:00:44:55:66 dev vnet1 vlan 10 master br0\n52:54:00:44:55:77 dev vnet1 vlan 20 master br0\na0:36:9f:00:00:01 dev eth0 vlan 20 master br0 stale\na0:36:9f:00:00:02 dev eth0 vlan 10 master br0\na0:36:9f:00:00:03 dev eth0 vlan 10 extern_learn master br0\n52:54:00:00:00:99 dev vnet9 vlan 30 master br1\n52:54:00:aa:bb:01 dev br0 vlan 1 master br0 permanent\n", "br1"], "expected": {"vnet9": [{"__tuple__": ["52:54:00:00:00:99", 30]}]}}, {"args": ["fe:54:00:11:22:33 dev vnet0 vlan 1 master br0 permanent\nfe:54:00:11:22:33 dev vnet0 master br0 permanent\n52:54:00:11:22:33 dev vnet0 vlan 20 master br0\n52:54:00:44:55:66 dev vnet1 vlan 10 master br0\n52:54:00:44:55:77 dev vnet1 vlan 20 master br0\na0:36:9f:00:00:01 dev eth0 vlan 20 master br0 stale\na0:36:9f:00:00:02 dev eth0 vlan 10 master br0\na0:36:9f:00:00:03 dev eth0 vlan 10 extern_learn master br0\n52:54:00:00:00:99 dev vnet9 vlan 30 master br1\n52:54:00:aa:bb:01 dev br0 vlan 1 master br0 permanent\n", "br9"], "expected": {}}, {"args": ["52:54:00:00:00:99 dev vnet9 master br1\nAA:BB:CC:DD:EE:FF dev veth5 master br0\naa:bb:cc:dd:ee:01 dev veth5 master br0 static\n", "br0"], "expected": {"veth5": [{"__tuple__": ["aa:bb:cc:dd:ee:ff", 0]}]}}, {"args": ["52:54:00:00:00:99 dev vnet9 master br1\nAA:BB:CC:DD:EE:FF dev veth5 master br0\naa:bb:cc:dd:ee:01 dev veth5 master br0 static\n", "br1"], "expected": {"vnet9": [{"__tuple__": ["52:54:00:00:00:99", 0]}]}}, {"args": ["", "br0"], "expected": {}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-vlan-devices', 5, 'func', 'VLAN-интерфейсы из ip -d link', 'Напишите функцию vlan_devices(text): text - вывод ip -d link show для нескольких интерфейсов. Запись интерфейса состоит из заголовка (строка с первого символа, вида ''3: eth0.100@eth0: <FLAGS> ... mtu 1500 ...'') и отступных строк с деталями. Интерфейс - VLAN, если в его деталях есть строка ''vlan protocol <протокол> id <номер>'' с необязательным ''<ФЛАГИ,ЧЕРЕЗ,ЗАПЯТУЮ>'' после номера. Верните словарь {имя: (родитель, номер, протокол, mtu, флаги)} только для VLAN-интерфейсов. Имя - слово после ''N: '' до ''@'' или до '':''; родитель - часть после ''@'' (пустая строка, если ''@'' нет); mtu - число после ''mtu'' в заголовке; протокол - как напечатан (802.1Q или 802.1ad); флаги - отсортированный список слов из <...> после номера, пустой список, если угловых скобок там нет. Строки деталей других интерфейсов (bridge, veth, bond) не должны попасть в результат; строка vlan может содержать после флагов другие слова (например bridge_slave state ...) - их игнорируйте.', 'def vlan_devices(text):
    pass
', 'Запоминайте текущий заголовок и разбирайте только отступные строки, начинающиеся с ''vlan protocol''. Регулярка: r''\s*vlan protocol (\S+) id (\d+)(?: <([^>]*)>)?''.', '{"func": "vlan_devices", "tests": [{"args": ["2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535 addrgenmode eui64 numtxqueues 1 numrxqueues 1\n3: eth0.100@eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 100 <REORDER_HDR> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n4: br0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535\n    bridge forward_delay 1500 hello_time 200 max_age 2000 ageing_time 30000 stp_state 0 priority 32768 vlan_filtering 0 vlan_protocol 802.1Q bridge_id 8000.525400123456\n"], "expected": {"eth0.100": {"__tuple__": ["eth0", 100, "802.1Q", 1500, ["REORDER_HDR"]]}}}, {"args": ["2: bond0: <BROADCAST,MULTICAST,MASTER,UP,LOWER_UP> mtu 9000 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 3c:fd:fe:00:11:22 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535\n    bond mode 802.3ad miimon 100\n5: bond0.50@bond0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 9000 qdisc noqueue master ovirtmgmt state UP mode DEFAULT group default qlen 1000\n    link/ether 3c:fd:fe:00:11:22 brd ff:ff:ff:ff:ff:ff promiscuity 1 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 50 <REORDER_HDR> bridge_slave state forwarding priority 32 cost 2 hairpin off guard off\n6: bond0.60@bond0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 3c:fd:fe:00:11:22 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1ad id 60 <REORDER_HDR,LOOSE_BINDING> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n7: ovirtmgmt: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 9000 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 3c:fd:fe:00:11:22 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535\n    bridge forward_delay 1500 hello_time 200 max_age 2000 ageing_time 30000 stp_state 0 priority 32768 vlan_filtering 0\n"], "expected": {"bond0.50": {"__tuple__": ["bond0", 50, "802.1Q", 9000, ["REORDER_HDR"]]}, "bond0.60": {"__tuple__": ["bond0", 60, "802.1ad", 1500, ["LOOSE_BINDING", "REORDER_HDR"]]}}}, {"args": ["9: veth0@if8: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 4a:ec:1b:00:aa:01 brd ff:ff:ff:ff:ff:ff link-netnsid 0 promiscuity 0 minmtu 68 maxmtu 65535\n    veth addrgenmode eui64 numtxqueues 1 numrxqueues 1\n"], "expected": {}}, {"args": ["11: br-lan.20@br-lan: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1496 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 84:16:f9:7c:ce:9f brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 20 <REORDER_HDR> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n12: vlan3999: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 84:16:f9:7c:ce:9f brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 3999 <REORDER_HDR,GVRP,MVRP> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n"], "expected": {"br-lan.20": {"__tuple__": ["br-lan", 20, "802.1Q", 1496, ["REORDER_HDR"]]}, "vlan3999": {"__tuple__": ["", 3999, "802.1Q", 1500, ["GVRP", "MVRP", "REORDER_HDR"]]}}}, {"args": [""], "expected": {}}, {"args": ["2: eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc fq_codel state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535 addrgenmode eui64 numtxqueues 1 numrxqueues 1\n3: eth0.100@eth0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 100 <REORDER_HDR> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n4: br0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 52:54:00:12:34:56 brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 68 maxmtu 65535\n    bridge forward_delay 1500 hello_time 200 max_age 2000 ageing_time 30000 stp_state 0 priority 32768 vlan_filtering 0 vlan_protocol 802.1Q bridge_id 8000.525400123456\n9: veth0@if8: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 4a:ec:1b:00:aa:01 brd ff:ff:ff:ff:ff:ff link-netnsid 0 promiscuity 0 minmtu 68 maxmtu 65535\n    veth addrgenmode eui64 numtxqueues 1 numrxqueues 1\n11: br-lan.20@br-lan: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1496 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 84:16:f9:7c:ce:9f brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 20 <REORDER_HDR> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n12: vlan3999: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 qdisc noqueue state UP mode DEFAULT group default qlen 1000\n    link/ether 84:16:f9:7c:ce:9f brd ff:ff:ff:ff:ff:ff promiscuity 0 minmtu 0 maxmtu 65535\n    vlan protocol 802.1Q id 3999 <REORDER_HDR,GVRP,MVRP> addrgenmode eui64 numtxqueues 1 numrxqueues 1\n"], "expected": {"eth0.100": {"__tuple__": ["eth0", 100, "802.1Q", 1500, ["REORDER_HDR"]]}, "br-lan.20": {"__tuple__": ["br-lan", 20, "802.1Q", 1496, ["REORDER_HDR"]]}, "vlan3999": {"__tuple__": ["", 3999, "802.1Q", 1500, ["GVRP", "MVRP", "REORDER_HDR"]]}}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-ip-script', 6, 'func', 'Скрипт ip link: итоговая топология', 'Смоделируйте последовательность команд ip link. commands - список строк. Поддерживаются: ''ip link add NAME type bridge'', ''ip link add NAME type dummy'', ''ip link add NAME type veth peer name PEER'' (создаёт два устройства), ''ip link add link PARENT name NAME type vlan id N'', ''ip link set NAME up'', ''ip link set NAME down'', ''ip link set NAME master BRIDGE'', ''ip link set NAME nomaster'', ''ip link del NAME'' (и ''delete''). Новое устройство выключено (down) и без мастера. Команда не выполняется (считается ошибкой, состояние не меняется), если: имя при создании уже занято, у veth имя пира совпадает с именем устройства или занято; родитель VLAN не существует; номер VLAN вне 1..4094; у этого родителя уже есть VLAN с таким номером; устройство не существует (для set и del); в master указано несуществующее устройство, не мост или само устройство; сам NAME - мост (мост нельзя сделать портом); команда не из списка выше. Удаление устройства: его порты теряют мастера, удаляются все его VLAN-интерфейсы (рекурсивно), удаляется пир veth. nomaster без мастера - не ошибка. master устройству, уже стоящему в другом мосту, переносит его. Напишите функцию apply_script(commands): верните (lines, failed), где lines - отсортированные по имени строки ''<имя> <тип> <up|down> <мастер или ->'' (тип: bridge, dummy, veth, vlan), а failed - число неудавшихся команд.', 'def apply_script(commands):
    pass
', 'Словарь устройств name -> {type, up, master, parent, peer}. Удаление делайте функцией: она сама чистит мастеров, детей и пира.', '{"func": "apply_script", "tests": [{"args": [["ip link add br0 type bridge", "ip link set br0 up", "ip link add veth0 type veth peer name veth1", "ip link set veth1 master br0", "ip link set veth0 up", "ip link set veth1 up"]], "expected": {"__tuple__": [["br0 bridge up -", "veth0 veth up -", "veth1 veth up br0"], 0]}}, {"args": [["ip link add br0 type bridge", "ip link add br0 type dummy", "ip link add d0 type dummy", "ip link set d0 master d0", "ip link set d0 master br0", "ip link set d0 master br9", "ip link set br0 master br0"]], "expected": {"__tuple__": [["br0 bridge down -", "d0 dummy down br0"], 4]}}, {"args": [["ip link add eth0 type dummy", "ip link add link eth0 name eth0.100 type vlan id 100", "ip link add link eth0 name eth0.101 type vlan id 100", "ip link add link eth0 name eth0.0 type vlan id 0", "ip link add link eth0 name eth0.4095 type vlan id 4095", "ip link add link eth0 name eth0.4094 type vlan id 4094", "ip link add link nope name n.1 type vlan id 1"]], "expected": {"__tuple__": [["eth0 dummy down -", "eth0.100 vlan down -", "eth0.4094 vlan down -"], 4]}}, {"args": [["ip link add br0 type bridge", "ip link add br1 type bridge", "ip link add p0 type dummy", "ip link set p0 master br0", "ip link set p0 master br1", "ip link set p0 nomaster", "ip link set p0 nomaster", "ip link set p1 nomaster"]], "expected": {"__tuple__": [["br0 bridge down -", "br1 bridge down -", "p0 dummy down -"], 1]}}, {"args": [["ip link add br0 type bridge", "ip link add veth0 type veth peer name veth1", "ip link add link veth0 name veth0.7 type vlan id 7", "ip link set veth1 master br0", "ip link set veth0.7 master br0", "ip link del veth0"]], "expected": {"__tuple__": [["br0 bridge down -"], 0]}}, {"args": [["ip link add br0 type bridge", "ip link add d0 type dummy", "ip link add d1 type dummy", "ip link set d0 master br0", "ip link set d1 master br0", "ip link delete br0", "ip link del br0"]], "expected": {"__tuple__": [["d0 dummy down -", "d1 dummy down -"], 1]}}, {"args": [["ip link add a type veth peer name a", "ip link add a type veth peer name b", "ip link add c type veth peer name b", "ip link add c type veth peer name d", "ip link add e type veth", "ip addr add 10.0.0.1/24 dev c", "ip link set c sideways", ""]], "expected": {"__tuple__": [["a veth down -", "b veth down -", "c veth down -", "d veth down -"], 6]}}, {"args": [[]], "expected": {"__tuple__": [[], 0]}}]}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (19, 10, 'la10-vm-diagnose', 7, 'func', 'Почему у машины нет сети', 'Напишите функцию diagnose(link_text, vlan_text, filtering, bridge, tap, vid): link_text - вывод bridge link show, vlan_text - вывод bridge vlan show (формат из прошлых задач), filtering - True, если у моста vlan_filtering 1, bridge - ожидаемый мост, tap - порт виртуальной машины, vid - VLAN, в котором должна работать машина (она шлёт и принимает кадры без тега). Строка bridge link выглядит так: ''12: vnet0: <FLAGS> mtu 1500 master br0 state forwarding priority 32 cost 100'' (у veth имя имеет вид veth0@veth1, берите часть до ''@''). Верните первую найденную причину, проверяя по порядку: ''no-port'' - порта tap нет в link_text; ''wrong-bridge:<мост>'' - порт принадлежит другому мосту; ''state:<состояние>'' - состояние порта не forwarding; затем, только если filtering равно True: ''no-vlan'' - vid нет среди VLAN порта; ''pvid:<n>'' - PVID порта не равен vid (n - его номер или слово none, если PVID нет); ''tagged'' - у vid нет флага Egress Untagged (машина получит кадры с тегом). Если всё в порядке, верните ''ok''.', 'def diagnose(link_text, vlan_text, filtering, bridge, tap, vid):
    pass
', 'Из link_text достаньте (master, state) для tap регуляркой с ''\smaster (\S+) state (\S+)''; из vlan_text соберите VLAN, PVID и untagged только для строк порта tap.', '{"func": "diagnose", "tests": [{"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet0", 20], "expected": "ok"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet1", 10], "expected": "ok"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet1", 20], "expected": "pvid:10"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet1", 30], "expected": "no-vlan"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet9", 20], "expected": "no-port"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", false, "br0", "vnet1", 99], "expected": "ok"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet3", 20], "expected": "state:disabled"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet2", 20], "expected": "state:learning"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\neth0              1 Egress Untagged\n                  10\n                  20\nvnet0             20 PVID Egress Untagged\nvnet1             10 PVID Egress Untagged\n                  20\nbr0               1 PVID Egress Untagged\n", true, "br0", "vnet5", 20], "expected": "wrong-bridge:virbr0"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\nbond0             1 Egress Untagged\n                  50\n                  60\nvnet0             50 PVID Egress Untagged\nvnet1             60\n", true, "virbr0", "vnet5", 60], "expected": "no-vlan"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\nbond0             1 Egress Untagged\n                  50\n                  60\nvnet0             50 PVID Egress Untagged\nvnet1             60\n", true, "br0", "vnet1", 60], "expected": "pvid:none"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\nvnet0             20 PVID\nvnet1             20 PVID Egress Untagged\n", true, "br0", "vnet0", 20], "expected": "tagged"}, {"args": ["3: eno1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 5\n12: vnet0: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n13: vnet1: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state forwarding priority 32 cost 100\n14: vnet2: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state learning priority 32 cost 100\n15: vnet3: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master br0 state disabled priority 32 cost 100\n16: vnet5: <BROADCAST,MULTICAST,UP,LOWER_UP> mtu 1500 master virbr0 state forwarding priority 32 cost 100\n", "port              vlan-id\nvnet0             20 PVID\nvnet1             20 PVID Egress Untagged\n", true, "br0", "vnet1", 20], 